const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(v);
const exact=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(v);
const pct=v=>`${v.toFixed(1)}%`, btn=(label,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
let plan=emptyPlan(), annual, storageReady=false, saving=false, editorSave, symbols, undoPlan, channel;
let quoteKey='',refreshing=false,quoteReport='',planSummaries=[];
const titleMap={accounts:'Accounts',overview:'Overview',holdings:'Stocks & funds',trades:'Buy / sell plan',funding:'Funding',retirement:'Retirement',annual:'Yearly assumptions',settings:'Plan settings',data:'Data & backups',modules:'Modules',bonds:'Bonds, CDs & treasuries',annuities:'Annuities',other:'Private investments'};
const currentView=()=>Object.hasOwn(titleMap,location.hash.slice(1))?location.hash.slice(1):'overview';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function status(message,error=false){$('#save-state').textContent=message;$('#save-state').style.color=error?'#a13e39':'';}
async function commit(next){if(saving)throw Error('A save is in progress. Please retry.');if(!storageReady)throw Error('Database unavailable. Export your data before retrying.');recordDerivedAccountHistory(next,plan,(p,a)=>accountValue(a,p));validatePlan(next);saving=true;status('Saving…');try{await database.write(next);plan=next;planSummaries=planSummaries.map(x=>x.id===database.activeId()?{...x,name:next.settings.name}:x);channel?.postMessage('changed');status('✓ Saved on this browser');}catch(e){status('Save failed — changes not saved',true);throw e;}finally{saving=false;}}
const effectiveAnnual=()=>plan.annualData||annual;
const heading=(title,subtitle,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${esc(plan.settings.name)}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;
const empty=(title,text,action='')=>`<div class="empty"><div class="empty-mark">↗</div><strong>${title}</strong><p>${text}</p>${action}</div>`;
const dollarFields=new Set(['cash','cashContribution','primarySalary','spouseSalary','price','balance','basis','contribution','amount','fee','oneTime','cashAmount','upfrontPremium','annualPremium','monthlyIncome','principal','value']);
function precisionLabel(increment,exactMode){return exactMode?'Use $'+increment.toLocaleString('en-US')+' steps':increment===1?'Exact dollars & cents':'Exact dollars';}
function field(name,label,value='',type='number',opts=''){if(type==='number'&&dollarFields.has(name)){opts=opts.replace('min="0.01"','min="0"');if(!opts.includes('min='))opts+=' min="-1000000000000"';}const cents=type==='number'&&(opts.includes('data-share-price')||name==='fee'),dollar=type==='number'&&dollarFields.has(name)&&!cents,increment=cents?1:1000,exactMode=(dollar||cents)&&value!==''&&value!=null&&Math.abs(Number(value)/increment-Math.round(Number(value)/increment))>1e-9;return `<label>${label}<input name="${name}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${type==='number'?`step="${(dollar||cents)&&!exactMode?increment:'any'}"`:''} ${dollar||cents?`data-dollar="true" data-increment="${increment}"`:''} ${opts}>${dollar||cents?`<button class="text-button dollar-precision" type="button" data-dollar-precision aria-pressed="${exactMode}">${precisionLabel(increment,exactMode)}</button>`:''}</label>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-dollar-precision]');if(!b)return;e.preventDefault();const input=b.closest('label').querySelector('input[type="number"]'),exactMode=input.step!=='any';const increment=Number(input.dataset.increment)||1000;input.step=exactMode?'any':String(increment);b.setAttribute('aria-pressed',String(exactMode));b.textContent=precisionLabel(increment,exactMode);input.setCustomValidity('');});
document.addEventListener('invalid',e=>{if(e.target.matches('input[data-dollar]')&&e.target.validity.stepMismatch)e.target.setCustomValidity('Use $'+Number(e.target.dataset.increment).toLocaleString('en-US')+' increments or select '+precisionLabel(Number(e.target.dataset.increment),false)+' for this amount.');},true);
document.addEventListener('input',e=>{if(e.target.matches('input[data-dollar]'))e.target.setCustomValidity('');});
function select(name,label,values,value){return `<label>${label}<select name="${name}" aria-label="${label}">${values.map(v=>`<option value="${esc(typeof v==='string'?v:v[0])}" ${(typeof v==='string'?v:v[0])===value?'selected':''}>${esc(typeof v==='string'?v:v[1])}</option>`).join('')}</select></label>`;}
function formData(form){const f=new FormData(form);return {text:k=>String(f.get(k)||'').trim(),num:k=>Number(f.get(k)),nullable:k=>f.get(k)===''?null:Number(f.get(k)),checked:k=>f.has(k)};}
function openEditor(title,html,save){$('#editor-form button[type="submit"]').textContent='Save changes';$('#editor-form').oninput=null;$('#editor-title').textContent=title;$('#editor-fields').innerHTML=html;if(!config.externalLinks)$('#editor-fields').querySelectorAll('a[href^="https:"]').forEach(a=>a.hidden=true);$('#editor-error').textContent='';editorSave=save;$('#editor').showModal();}
$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();
$('#editor-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await editorSave(formData(e.target));$('#editor').close();render();}catch(err){$('#editor-error').textContent=err.message;}finally{b.disabled=false;}};
function chart(rows,baseline){const w=720,h=220,left=65,right=10,top=15,bottom=28,max=Math.max(1,...rows.map(r=>r.total),...baseline.map(r=>r.total)),min=Math.min(0,...rows.map(r=>r.total));const x=i=>left+(w-left-right)*i/Math.max(rows.length-1,1),y=v=>top+(h-top-bottom)*(1-(v-min)/(max-min));const points=rows.map((r,i)=>`${x(i)},${y(r.total)}`).join(' '),base=baseline.map((r,i)=>`${x(i)},${y(r.total)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Projected portfolio value by year. Exact values in the annual breakdown below.">${[0,.25,.5,.75,1].map(n=>{const v=min+(max-min)*n;return `<line x1="${left}" y1="${y(v)}" x2="${w-right}" y2="${y(v)}" stroke="#e7ede4" stroke-dasharray="3 4"/><text x="${left-10}" y="${y(v)+4}" text-anchor="end">${Math.abs(v)>=1e6?'$'+(v/1e6).toFixed(1)+'m':Math.abs(v)>=1000?'$'+(v/1000).toFixed(0)+'k':money(v)}</text>`;}).join('')}<polygon points="${left},${y(min)} ${points} ${x(rows.length-1)},${y(min)}" fill="#eaf0df" opacity=".65"/><polyline points="${base}" fill="none" stroke="#a4b6a8" stroke-width="2" stroke-dasharray="5 5"/><polyline points="${points}" fill="none" stroke="#296348" stroke-width="3" stroke-linejoin="round"/>${[...new Set([0,Math.floor((rows.length-1)/2),rows.length-1])].map(i=>`<text x="${x(i)}" y="${h-4}" text-anchor="middle">${rows[i].year}</text>`).join('')}</svg>`;}
function holdingTable(){return `<div class="table-wrap"><table><thead><tr><th>Investment</th><th>Account / owner</th><th class="num">Shares</th><th class="num">Starting value</th><th class="num">Price growth</th><th class="num">Yield</th><th>Actions</th></tr></thead><tbody>${plan.holdings.map(h=>`<tr data-holding="${esc(h.id)}"><td><span class="symbol">${esc(h.symbol||h.name)}</span><span class="sub">${esc(h.name)} · ${esc(h.type)}</span></td><td>${esc(h.account||'Unassigned')}<span class="sub">${esc(h.owner)} · ${esc(h.taxType)}</span>${h.accountId&&(plan.accounts||[]).find(a=>a.id===h.accountId)?.valuationMode==='manual'?'<span class="tag">Included in account total</span>':''}</td><td class="num">${h.valuationMode==='dollars'?'Dollar value':h.shares.toLocaleString('en-US',{maximumFractionDigits:6})}</td><td class="num">${exact(startingHoldingValue(h))}</td><td class="num">${pct(h.growth)}</td><td class="num">${pct(h.yield)}</td><td>${btn('Edit','edit-holding',h.id,'text-button')}${btn('Historical graph','holding-history',h.id,'text-button')}${btn('Remove','remove-holding',h.id,'text-button danger')}</td></tr>`).join('')}</tbody></table></div>`;}
function overview(){const result=project(plan,effectiveAnnual()),base=project(plan,effectiveAnnual(),false),last=result.rows.at(-1),start=plan.settings.cash+valuationHoldings(plan).reduce((a,h)=>a+startingHoldingValue(h),0)+initialBondValue(plan),div=valuationHoldings(plan).reduce((a,h)=>a+startingHoldingValue(h)*h.yield/100,0);return heading('Your investments, in perspective.','Plan your investments, explore changes, and see the years ahead.',`<a class="button" href="#data">Export / import</a>${btn('+ Add investment','add-holding','','primary')}`)+`<div class="cards"><div class="card accent"><div class="card-label">Starting net worth</div><div class="card-value">${money(start)}</div><div class="card-note">${valuationHoldings(plan).length} valued positions + ${money(initialBondValue(plan))} fixed-income principal + ${money(plan.settings.cash)} cash</div></div><div class="card"><div class="card-label">Projected value · ${last.year}</div><div class="card-value">${money(last.total)}</div><div class="card-note">${money(last.real)} in start-year dollars</div></div><div class="card"><div class="card-label">Starting annual dividends</div><div class="card-value">${money(div)}</div><div class="card-note">Based on your starting values and yields</div></div><div class="card"><div class="card-label">Planned transactions</div><div class="card-value">${plan.trades.length.toString().padStart(2,'0')}</div><div class="card-note">${plan.trades.filter(t=>t.side==='buy').length} buys · ${plan.trades.filter(t=>t.side==='sell').length} sells</div></div></div>`+
`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Portfolio outlook</h2><p class="muted">End-of-year value · ${plan.settings.startYear}–${last.year}</p></div><a class="button text-button" href="#settings">Edit horizon ↗</a></div>${result.rows.some(r=>r.total!==0)?chart(result.rows,base.rows):empty('Start with your first investment','Add a stock or fund to build your portfolio projection.',btn('+ Add investment','add-holding','','primary'))}<div class="legend"><span><i></i>With planned trades</span><span><i class="baseline"></i>Without planned trades</span></div></section><section class="panel"><h2>Starting allocation</h2><p class="muted">How your portfolio is distributed</p>${start>0?[...valuationHoldings(plan).map(h=>({label:h.symbol||h.name,value:startingHoldingValue(h)})),{label:'Bonds / CDs / treasuries',value:initialBondValue(plan)},{label:'Cash',value:plan.settings.cash}].filter(h=>h.value>0).sort((a,b)=>b.value-a.value).slice(0,8).map(h=>`<div class="allocation"><span>${esc(h.label)}</span><b>${pct(h.value/start*100)}</b></div><div class="bar"><div style="width:${h.value/start*100}%"></div></div>`).join(''):'<div class="empty">Your allocation will appear here.</div>'}<p class="muted">${plan.holdings.length>7?'Largest positions shown. ':''}Values use prices you enter.</p></section></div>`+
`${result.warnings.length?`<div class="notice"><b>Plan needs attention</b><div class="warning-list">${result.warnings.map(w=>`<div>${esc(w)}</div>`).join('')}</div></div>`:''}${overviewAccounts()}${cashFlowView(result,esc,money)}<section class="panel"><div class="panel-head"><div><h2>Stocks & funds</h2><p class="muted">Your individually tracked stocks and funds</p></div><a href="#holdings">Manage investments →</a></div>${plan.holdings.length?holdingTable():empty('A place for every holding','Track stocks, ETFs and mutual funds, or use a single account total under Accounts.')}</section>${moduleUI.overviewSections(result.rows)}<section class="panel"><div class="panel-head"><div><h2>Annual breakdown</h2><p class="muted">Cash, investments and bond principal combined. Annuity premiums reduce cash; surrender values are excluded. Contributions and withdrawals are external flows. Retirement withdrawals are included in net contributions and shown separately for reference.</p></div>${btn('Export CSV','export-csv')}</div><details><summary>View ${result.rows.length} projected years</summary><div class="table-wrap"><table><thead><tr><th>Year</th><th class="num">Opening</th><th class="num">Net contributions</th><th class="num">Retirement withdrawals</th><th class="num">Price change</th><th class="num">Dividends & income</th><th class="num">Annuity premiums</th><th class="num">Fees</th><th class="num">Cash</th><th class="num">Ending value</th><th class="num">Inflation adjusted</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${r.year}</td>${['opening','external','retirementWithdrawal','growth','income','annuityPremiums','fees','cash','total','real'].map(k=>`<td class="num">${money(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section>${method()}`;}
function method(){return `<details class="panel"><summary>How the projection works</summary><ol class="method"><li>Starting holding value is your entered dollar balance or shares × entered price, according to the selected mode. Prices are manual snapshots, not live quotes.</li><li>Each year starts with the cash contribution, then planned trades in their displayed order. Sales can fund later buys. Fees reduce total wealth. Unfunded buys and oversized sales are skipped and flagged.</li><li>Price growth excludes dividends. Both rates apply to the value after trades. Dividends are either reinvested at year end or paid into cash. Do not enter a total-return rate plus a separate yield, which would double-count dividends.</li><li>Your periodic investment source selects fixed-dollar contributions, salary percentages, or none. One-time changes work in every mode. Contributions and withdrawals happen at year end. Positive amounts are new outside money. Negative amounts leave the portfolio, with withdrawals limited to the holding value. Use a sell transaction to move proceeds into cash.</li><li>Annual overrides apply only to their specified year, then the holding's base assumptions resume. Salary growth and inflation use an exact-year annual setting, otherwise the defaults.</li><li>Cost basis follows a proportional average-cost planning approximation. Buy fees and reinvested dividends increase basis; sales remove proportional basis. This is not a tax-lot calculation. Account categories are labels; taxes, withdrawal penalties, contribution limits and retirement distributions are not modeled.</li><li>Cash earns 0%. All amounts are USD. No trades are sent to a broker. Projection years are estimates, not market forecasts.</li></ol></details>`;}
function holdings(){return heading('Stocks & funds','Add as many holdings as your plan needs. The same symbol can belong to different accounts.',btn('+ Add investment','add-holding','','primary'))+`<section class="panel"><div class="panel-head"><h2>Investment library <span class="tag">${plan.holdings.length} holdings</span></h2><input class="filter" id="holding-search" type="search" placeholder="Filter symbol, name or account" aria-label="Filter holdings"></div>${plan.holdings.length?holdingTable():empty('Build your investment list','Start with a symbol lookup or enter any investment manually.',btn('+ Add investment','add-holding','','primary'))}<p id="filter-empty" class="muted" hidden>No matching holdings.</p></section>${method()}`;}
function editHolding(id,accountId){const existing=plan.holdings.find(h=>h.id===id);const h=existing?structuredClone(existing):{id:uid(),symbol:'',name:'',type:'ETF',account:'',owner:'Both',taxType:'Taxable',shares:0,price:0,basis:0,growth:0,yield:0,contribution:0,contributionGrowth:0,primaryPct:0,spousePct:0,reinvest:true,contributionMode:'none',valuationMode:'dollars',balance:0};
 if(!existing&&accountId){const account=(plan.accounts||[]).find(a=>a.id===accountId);if(account){h.accountId=account.id;h.account=account.name;h.owner=account.owner;h.taxType=account.taxType;}}
 h.contributionMode??=(h.primaryPct||h.spousePct)?(h.contribution?'both':'salary'):(h.contribution?'fixed':'none');
openEditor(id?'Edit investment':'Add an investment',`<div class="snapshot"><label>Find a stock or fund<input id="lookup" type="search" placeholder="Try VTI, Fidelity, Apple…" autocomplete="off"></label><div id="lookup-results"></div><p class="muted">Search over 13,000 US-listed securities, including stocks and ETFs, plus selected mutual funds. Selecting a result fills in its ticker, name and type. This directory does not include every mutual fund or foreign listing. ${config.quoteMode==='disabled'?'Enter prices and balances manually in this edition.':'Prices are updated separately.'} <a id="lookup-web" href="https://finance.yahoo.com/lookup/" target="_blank" rel="noopener noreferrer">Look up on Yahoo — enter details manually ↗</a></p></div><div class="grid-form">${field('symbol','Ticker symbol',h.symbol,'text','maxlength="24"')}${field('name','Investment name',h.name,'text','required maxlength="160"')}${select('type','Investment type',['Stock','ETF','Mutual fund','Other'],h.type)}${select('accountId','Portfolio account',[['','Standalone investment'],...(plan.accounts||[]).map(a=>[a.id,a.name+(a.valuationMode==='manual'?' · included in manual total':'')])],h.accountId||'')}${field('account','Account label (standalone)',h.account,'text','maxlength="160"')}${select('owner','Owner',['Primary','Spouse','Both'],h.owner)}${select('taxType','Account category',['Taxable','Traditional retirement','Roth'],h.taxType)}${select('valuationMode','Track this investment using',[['dollars','Dollar value only'],['shares','Shares and share price']],h.valuationMode||'shares')}${field('balance','Starting investment value ($)',h.balance??h.shares*h.price,'number','required min="0"')}${field('shares','Starting shares',h.shares,'number','required min="0"')}${field('price','Entered share price ($)',h.price,'number','required min="0" data-share-price inputmode="decimal"')}<div id="share-calculator"><p class="muted">Optional: enter a dollar value above, then calculate shares from the entered price.</p><button type="button" id="calculate-shares">Calculate shares</button>${h.quote&&config.quoteMode!=='disabled'?`<button type="button" id="quote-shares">Use retrieved price & calculate shares</button><p class="muted">${esc(h.quote.marketTime||'Quote date not supplied')} · ${exact(h.quote.price)} per share. This replaces the entered share price.</p>`:''}<p id="share-calculation-result" class="muted" role="status"></p></div><label class="check"><input type="checkbox" name="recordHistory" checked>Record this entered value in history when saving</label>${field('basis','Total starting cost basis ($, optional)',h.basis||'','number','min="0" placeholder="Not needed for projections"')}${field('growth','Annual price growth (%)',h.growth,'number','required min="-100" max="100"')}${field('yield','Annual dividend yield (%)',h.yield,'number','required min="0" max="100"')}<label class="check"><input type="checkbox" name="reinvest" ${h.reinvest?'checked':''}>Reinvest dividends</label>${select('contributionMode','Periodic investment source',[['none','None'],['fixed','Fixed dollar amount'],['salary','Salary percentage'],...(h.contributionMode==='both'?[['both','Fixed + salary (existing plan)']]:[])],h.contributionMode)}${field('contribution','Annual contribution (+) / withdrawal (−)',h.contribution,'number','required')}${field('contributionGrowth','Annual contribution growth (%)',h.contributionGrowth,'number','required min="-100" max="100"')}${field('primaryPct','Primary salary contribution (%)',h.primaryPct,'number','required min="0" max="100"')}${field('spousePct','Spouse salary contribution (%)',h.spousePct,'number','required min="0" max="100"')}</div><p class="muted">For a manual-total account, this holding is informational and is not added to the portfolio total. Dollar value mode needs no share count or price; update its balance manually. ${config.quoteMode==='disabled'?'Enter the share price manually in this edition.':'Share mode supports ticker price updates.'} Switching modes keeps both sets of saved inputs. Growth and yield are your assumptions. A zero starting balance lets you plan a future purchase. Salary amounts are in Funding.</p>`,async f=>{const next=structuredClone(plan),value={...h};for(const k of ['symbol','name','type','account','owner','taxType','contributionMode'])value[k]=f.text(k);value.symbol=value.symbol.toUpperCase();if(value.symbol!==h.symbol)delete value.quote;value.accountId=f.text('accountId');if(value.accountId)value.account=next.accounts.find(a=>a.id===value.accountId).name;for(const k of ['shares','price','basis','growth','yield','contribution','contributionGrowth','primaryPct','spousePct'])value[k]=f.num(k);value.valuationMode=f.text('valuationMode');value.balance=f.num('balance');value.reinvest=f.checked('reinvest');if(f.checked('recordHistory'))recordSnapshot(value,{kind:value.valuationMode==='dollars'?'value':'price',value:value.valuationMode==='dollars'?value.balance:value.price});const index=next.holdings.findIndex(x=>x.id===h.id);if(index<0)next.holdings.push(value);else next.holdings[index]=value;await commit(next);});
const modeControl=$('#editor-form').elements.contributionMode;
 const valueControl=$('#editor-form').elements.valuationMode,showValueFields=()=>{const form=$('#editor-form');form.elements.balance.closest('label').hidden=false;$('#share-calculator').hidden=valueControl.value!=='shares';for(const k of ['shares','price'])form.elements[k].closest('label').hidden=valueControl.value!=='shares';};valueControl.onchange=showValueFields;showValueFields();
 const calculateShares=useQuote=>{const form=$('#editor-form'),out=$('#share-calculation-result');try{if(useQuote&&form.elements.symbol.value.trim().toUpperCase()!==h.symbol)throw Error('The ticker changed. Retrieve a quote for the new ticker first.');const price=useQuote?h.quote.price:Number(form.elements.price.value),amount=Number(form.elements.balance.value),shares=sharesFromValue(amount,price);if(useQuote)form.elements.price.value=price;form.elements.shares.value=shares;out.textContent=`${shares.toLocaleString('en-US',{maximumFractionDigits:6})} shares from ${exact(amount)} at ${exact(price)}. Fractional shares are allowed in this projection.`;}catch(err){out.textContent=err.message;}};$('#calculate-shares').onclick=()=>calculateShares(false);if($('#quote-shares'))$('#quote-shares').onclick=()=>calculateShares(true);
 const showContributionFields=()=>{for(const k of ['contribution','contributionGrowth'])$('#editor-form').elements[k].closest('label').hidden=!['fixed','both'].includes(modeControl.value);for(const k of ['primaryPct','spousePct'])$('#editor-form').elements[k].closest('label').hidden=!['salary','both'].includes(modeControl.value);};modeControl.onchange=showContributionFields;showContributionFields();
$('#lookup').oninput=async e=>{const q=e.target.value.trim().toLowerCase();$('#lookup-web').href='https://finance.yahoo.com/lookup/?s='+encodeURIComponent(q);if(!q){$('#lookup-results').innerHTML='';return;}const manual=/^[a-z0-9.^:=_-]{1,24}$/i.test(q)?`<button type="button" data-use-ticker="${esc(q.toUpperCase())}">Use ticker ${esc(q.toUpperCase())} — enter name manually</button>`:'';
 const selectResult=e=>{const manualButton=e.target.closest('[data-use-ticker]');if(manualButton){const form=$('#editor-form');if(form.elements.symbol.value!==manualButton.dataset.useTicker)form.elements.name.value='';form.elements.symbol.value=manualButton.dataset.useTicker;form.elements.name.focus();$('#lookup-results').innerHTML='';return;}const b=e.target.closest('[data-symbol]');if(!b)return;const result=symbols.find(s=>s[0]===b.dataset.symbol);for(const [k,v] of [['symbol',result[0]],['name',result[1]],['type',result[2]]])$('#editor-form').elements[k].value=v;$('#lookup-results').innerHTML='';};
 try{symbols??=await fetch('data/symbols.json').then(r=>{if(!r.ok)throw Error();return r.json();});if($('#lookup')?.value.trim().toLowerCase()!==q)return;const matches=searchSymbols(symbols,q);$('#lookup-results').innerHTML=(matches.length?matches.map(s=>`<button type="button" data-symbol="${esc(s[0])}"><b>${esc(s[0])}</b> ${esc(s[1])} <span class="tag">${esc(s[2])}</span></button>`).join(''):'<p class="muted">No directory match. This does not mean your ticker is invalid. Add it manually below.</p>')+manual;$('#lookup-results').onclick=selectResult;}catch{if($('#lookup')?.value.trim().toLowerCase()!==q)return;$('#lookup-results').innerHTML='<p class="muted">Search directory unavailable. You can still enter the ticker and name manually.</p>'+manual;$('#lookup-results').onclick=selectResult;}};

}
function trades(){const r=project(plan,effectiveAnnual()),last=r.rows.at(-1),baseline=project(plan,effectiveAnnual(),false).rows.at(-1);return heading('Make room for your next move.','Explore purchases and sales without changing your starting holdings.',btn('+ Plan a transaction','add-trade','','primary'))+`<div class="cards"><div class="card accent"><div class="card-label">Starting cash</div><div class="card-value">${money(plan.settings.cash)}</div><a href="#funding">Edit cash balance ↗</a></div><div class="card"><div class="card-label">Planned buys</div><div class="card-value">${money(plan.trades.filter(t=>t.side==='buy').reduce((a,t)=>a+t.amount,0))}</div><div class="card-note">Before fees</div></div><div class="card"><div class="card-label">Planned sells</div><div class="card-value">${money(plan.trades.filter(t=>t.side==='sell').reduce((a,t)=>a+t.amount,0))}</div><div class="card-note">Before fees</div></div><div class="card"><div class="card-label">Projected trade impact · ${last.year}</div><div class="card-value">${money(last.total-baseline.total)}</div><div class="card-note">Compared with the same plan without trades</div></div></div><div class="notice">Transactions are modeled at the start of each year, in the order shown. Sell before buying to use the proceeds. A skipped trade has no effect on the projection.</div><section class="panel"><h2>Transaction schedule</h2>${plan.trades.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>Action</th><th>Investment</th><th class="num">Amount</th><th class="num">Fee</th><th>Result</th><th>Manage</th></tr></thead><tbody>${[...plan.trades].sort((a,b)=>a.year-b.year).map(t=>{const h=[...plan.holdings,...(plan.accounts||[])].find(h=>h.id===t.holdingId),status=r.tradeResults.find(x=>x.id===t.id)?.status;return `<tr><td>${t.year}</td><td><span class="tag ${t.side}">${t.side.toUpperCase()}</span></td><td><b>${esc(h.symbol||h.name)}</b><span class="sub">${esc(h.account)} ${esc(t.note)}</span></td><td class="num">${exact(t.amount)}</td><td class="num">${exact(t.fee)}</td><td class="${status==='Applied'?'success':'error'}">${esc(status)}</td><td>${btn('Edit','edit-trade',t.id,'text-button')}${btn('↑ Earlier','earlier-trade',t.id,'text-button')}${btn('Remove','remove-trade',t.id,'text-button danger')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Try a change to your plan','Schedule a purchase, a partial sale, or a rebalance.',btn('+ Plan a transaction','add-trade','','primary'))}</section>${method()}`;}
function editTrade(id){const positions=valuationHoldings(plan).filter(h=>plan.holdings.some(x=>x.id===h.id)||(plan.accounts||[]).some(x=>x.id===h.id));if(!positions.length){toast('Add an investment or a summary account first.');return;}const t=plan.trades.find(t=>t.id===id)||{id:uid(),holdingId:positions[0].id,side:'buy',year:plan.settings.startYear,amount:1000,fee:0,note:''};openEditor(id?'Edit planned transaction':'Plan a buy or sell',`<div class="grid-form">${select('holdingId','Investment',[...positions,...(t.id&&![...positions].some(x=>x.id===t.holdingId)?[...plan.holdings,...(plan.accounts||[])].filter(x=>x.id===t.holdingId):[])].map(h=>[h.id,`${h.symbol||h.name} · ${(plan.accounts||[]).some(a=>a.id===h.id)?(h.valuationMode==='mixed'?'Remaining investments in account':'Account total'):h.account||'Standalone investment'}${positions.some(x=>x.id===h.id)?'':' · excluded: select a valid source'}`]),t.holdingId)}${select('side','Transaction',[['buy','Buy'],['sell','Sell']],t.side)}${field('year','Plan year',t.year,'number','required min="1900" max="2300" step="1"')}${field('amount','Gross transaction amount ($)',t.amount,'number','required min="0.01"')}${field('fee','Fee ($)',t.fee,'number','required min="0"')}${field('note','Note',t.note,'text','maxlength="500"')}</div><p class="muted">Choose an account total to trade a manual dollar balance. In selected-holdings mode, choosing the account trades its remaining investments; select a named stock to trade that stock. Accounts calculated from holdings must be traded through their individual investments. Buys use available cash plus fees. Sales add proceeds minus fees to cash. Transactions use dollar amounts at the projected value; future share counts are not estimated.</p>`,async f=>{const next=structuredClone(plan),value={...t,holdingId:f.text('holdingId'),side:f.text('side'),year:f.num('year'),amount:f.num('amount'),fee:f.num('fee'),note:f.text('note')};const i=next.trades.findIndex(x=>x.id===t.id);if(i<0)next.trades.push(value);else next.trades[i]=value;await commit(next);});}
function annualView(){const a=effectiveAnnual();return heading('A plan that can change each year.','Update annual assumptions independently of your holdings and interface.',btn('+ Holding override','add-override','','primary'))+`<div class="two-col"><section class="panel"><h2>Default annual assumptions</h2><p class="muted">Used for years without an explicit annual entry. Editable planning assumptions, not forecasts.</p><form id="annual-defaults"><div class="grid-form">${field('inflation','Inflation (%)',a.defaults.inflation,'number','required min="-50" max="100"')}</div><div class="form-actions"><button class="primary">Save defaults</button></div></form></section><section class="panel"><h2>Separate annual data file</h2><p class="muted">Export or import annual assumptions without changing investments, trades or plan settings. Database backups also include the assumptions used by your plan.</p><div class="actions">${btn('Export annual data','export-annual')}<button data-action="choose-annual">Import annual data</button><input id="annual-file" type="file" accept=".json,application/json" hidden></div></section></div><section class="panel"><div class="panel-head"><div><h2>Year-specific assumptions</h2><p class="muted">Each entry applies only to that year. Salary growth is managed in Funding. Removing an annual entry resets both inflation and salary growth to their defaults.</p></div>${btn('+ Add year','add-year')}</div>${a.years.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>Inflation</th><th>Actions</th></tr></thead><tbody>${[...a.years].sort((a,b)=>a.year-b.year).map(y=>`<tr><td>${y.year}</td><td>${pct(y.inflation)}</td><td>${btn('Edit','edit-year',y.year,'text-button')}${btn('Remove','remove-year',y.year,'text-button danger')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">All projection years currently use the defaults above.</p>'}</section><section class="panel"><h2>Holding overrides by year</h2><p class="muted">Blank fields use the investment defaults. Enter 0 for an explicit zero. One-time changes are outside deposits or withdrawals.</p>${plan.overrides.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>Investment</th><th>Price growth</th><th>Yield</th><th>Annual contribution</th><th>One-time change</th><th>Actions</th></tr></thead><tbody>${[...plan.overrides].sort((a,b)=>a.year-b.year).map(o=>{const h=[...plan.holdings,...(plan.accounts||[])].find(h=>h.id===o.holdingId);const key=o.holdingId+':'+o.year;return `<tr><td>${o.year}</td><td>${esc(h.symbol||h.name)}<span class="sub">${esc(h.account)}</span></td><td>${o.growth===null?'Default':pct(o.growth)}</td><td>${o.yield===null?'Default':pct(o.yield)}</td><td>${o.contribution===null?'Default':money(o.contribution)}</td><td>${o.oneTime===null?'—':money(o.oneTime)}</td><td>${btn('Edit','edit-override',key,'text-button')}${btn('Remove','remove-override',key,'text-button danger')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Keep the future flexible','Change a return assumption, pause contributions, or plan a one-time withdrawal.')}</section>`;}
function editYear(id,salaryOnly=false){const a=effectiveAnnual(),y=a.years.find(y=>y.year===Number(id))||{year:plan.settings.startYear,...a.defaults};openEditor(salaryOnly?'Salary growth for one year':'Annual inflation',`<div class="grid-form">${field('year','Year',y.year,'number','required min="1900" max="2300"')}${salaryOnly?field('salaryGrowth','Salary growth (%)',y.salaryGrowth,'number','required min="-100" max="100"'):field('inflation','Inflation (%)',y.inflation,'number','required min="-50" max="100"')}</div>`,async f=>{const next=structuredClone(plan);next.annualData=structuredClone(a);if(id)next.annualData.years=next.annualData.years.filter(y=>y.year!==Number(id));next.annualData.years.push({year:f.num('year'),inflation:salaryOnly?(a.years.find(x=>x.year===f.num('year'))||a.defaults).inflation:f.num('inflation'),salaryGrowth:salaryOnly?f.num('salaryGrowth'):(a.years.find(x=>x.year===f.num('year'))||a.defaults).salaryGrowth});await commit(next);});}
function editOverride(key){if(!valuationHoldings(plan).length){toast('Add an investment or summary account first.');return;}const old=plan.overrides.find(o=>o.holdingId+':'+o.year===key),o=old||{holdingId:valuationHoldings(plan)[0].id,year:plan.settings.startYear,growth:null,yield:null,contribution:null,oneTime:null};openEditor('Holding assumptions for one year',`<div class="grid-form">${select('holdingId','Investment',[...plan.holdings,...(plan.accounts||[])].map(h=>[h.id,`${h.symbol||h.name} · ${h.account||'Unassigned'}`]),o.holdingId)}${field('year','Year',o.year,'number','required min="1900" max="2300"')}${field('growth','Price growth (%)',o.growth,'number','min="-100" max="100" placeholder="Use holding default"')}${field('yield','Dividend yield (%)',o.yield,'number','min="0" max="100" placeholder="Use holding default"')}${field('contribution','Annual contribution / withdrawal ($)',o.contribution,'number','placeholder="Use holding default"')}${field('oneTime','One-time deposit / withdrawal ($)',o.oneTime,'number','placeholder="No one-time change"')}</div><p class="muted">Annual contribution overrides apply to fixed-dollar mode. Salary mode uses the salary percentages; None disables all periodic contributions. One-time changes apply in every mode.</p>`,async f=>{const next=structuredClone(plan);if(old)next.overrides=next.overrides.filter(x=>x.holdingId+':'+x.year!==key);next.overrides.push({holdingId:f.text('holdingId'),year:f.num('year'),growth:f.nullable('growth'),yield:f.nullable('yield'),contribution:f.nullable('contribution'),oneTime:f.nullable('oneTime')});await commit(next);});}
function funding(){const s=plan.settings;return heading('Funding & withdrawals','Manage salary-based investing and money entering or leaving your plan.')+`<section class="panel"><form id="funding-form"><h2>Salary for investment contributions</h2><p class="muted">Used only for investments set to Salary percentage. Your full salary is not automatically deposited. Fixed-dollar investing and no periodic investment do not require a salary.</p><div class="grid-form">${field('primarySalary','Primary annual salary ($)',s.primarySalary,'number','required min="0"')}${field('spouseSalary','Spouse annual salary ($)',s.spouseSalary,'number','required min="0"')}${field('primarySalaryEndYear','Primary last working year (optional)',s.primarySalaryEndYear??'','number','min="1900" max="2300" placeholder="Continue throughout plan"')}${field('spouseSalaryEndYear','Spouse last working year (optional)',s.spouseSalaryEndYear??'','number','min="1900" max="2300" placeholder="Continue throughout plan"')}</div><div class="grid-form">${field('salaryGrowth','Default annual salary growth (%)',effectiveAnnual().defaults.salaryGrowth,'number','required min="-100" max="100"')}</div><p class="muted">Salary-based contributions continue through each person’s last working year and stop the following year. For retirement starting in 2036, enter 2035 as the last working year. Leave blank to continue throughout the plan. This annual model assumes a full final working year. Fixed-dollar contributions and cash flows continue separately. Salary growth applies after each projection year; year-specific rates below take precedence.</p><h2>Cash deposits & withdrawals</h2><div class="grid-form">${field('cash','Starting cash ($)',s.cash,'number','required min="0"')}${select('cashDirection','Annual cash flow',[['none','No recurring cash flow'],['deposit','Deposit into plan'],['withdrawal','Withdraw from plan']],s.cashContribution<0?'withdrawal':s.cashContribution>0?'deposit':'none')}${field('cashAmount','Annual cash amount ($)',Math.abs(s.cashContribution),'number','required min="0"')}</div><p class="muted">Enter a positive amount; the choice above determines whether it is added or withdrawn every year. Cash flows happen at the start of each year. A negative cash balance is flagged in the projection.</p><p class="notice">Selling an investment moves its proceeds into plan cash. A withdrawal removes money from the plan. Do not also count the same withdrawal against an investment below.</p><p><a href="#retirement">Plan retirement withdrawals and proportional sales →</a></p><div class="form-actions"><button class="primary">Save funding</button></div></form></section><section class="panel"><div class="panel-head"><h2>Year-specific salary growth</h2>${btn('+ Set year','add-salary-year')}</div><p class="muted">These rates apply only to their listed year. Other years use the default above. Editing salary growth preserves that year's inflation assumption.</p>${effectiveAnnual().years.length?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>Salary growth</th><th>Actions</th></tr></thead><tbody>${[...effectiveAnnual().years].sort((a,b)=>a.year-b.year).map(y=>`<tr><td>${y.year}</td><td>${pct(y.salaryGrowth)}</td><td>${btn('Edit salary growth','edit-salary-year',y.year,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">All years use default salary growth.</p>'}</section><section class="panel"><div class="panel-head"><div><h2>Investment contributions & withdrawals</h2><p class="muted">Set fixed dollars, salary percentages or none for each valued account or holding. These flows go directly into or out of the investment, separately from cash flows above.</p></div></div>${valuationHoldings(plan).length?`<div class="table-wrap"><table><thead><tr><th>Account / investment</th><th>Recurring funding</th><th>Manage</th></tr></thead><tbody>${valuationHoldings(plan).map(h=>{const mode=h.contributionMode??'both';return `<tr><td>${esc(h.symbol||h.name)}<span class="sub">${esc(h.account||h.name)}</span></td><td>${mode==='none'?'None':[['fixed','both'].includes(mode)?`${money(Math.abs(h.contribution))}/year ${h.contribution<0?'withdrawal':'contribution'}`:'',['salary','both'].includes(mode)?`Salary: primary ${h.primaryPct}%, spouse ${h.spousePct}%`:''].filter(Boolean).join(' + ')}</td><td>${btn('Edit funding',(plan.otherInvestments||[]).some(a=>a.id===h.id)?'edit-other':(plan.accounts||[]).some(a=>a.id===h.id)?'edit-account':'edit-holding',h.id,'text-button')}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="muted">Add an account or investment to set its periodic funding.</p>'}<p class="muted">For recurring investment withdrawals, choose Fixed dollar amount and enter a negative annual contribution. For a withdrawal in just one year, use a negative one-time amount in Yearly assumptions. Investment withdrawals occur at year end and are limited to available investment value.</p><a href="#annual">Plan a one-time deposit or withdrawal →</a></section>`;}
function retirement(){const s=plan.settings,r=s.retirement||{enabled:false,startYear:s.startYear+Math.min(10,s.years-1),rate:0},rows=project(plan,effectiveAnnual()).rows;return heading('Retirement withdrawals','Plan retirement spending with cash first, then proportional investment sales.')+`<section class="panel"><form id="retirement-form"><label class="check"><input type="checkbox" name="enabled" ${r.enabled?'checked':''}>Enable retirement withdrawals</label><div class="grid-form">${field('startYear','First withdrawal year',r.startYear,'number','required min="1900" max="2300"')}${select('mode','Withdrawal amount type',[['percent','Percentage of portfolio'],['dollars','Dollar amount with annual growth']],r.mode||'percent')}${field('rate','Annual withdrawal rate (%)',r.rate,'number','required min="0" max="100"')}${field('amount','First-year withdrawal amount ($)',r.amount??0,'number','required min="0"')}${field('amountGrowth','Annual withdrawal growth (%)',r.amountGrowth??0,'number','required min="-100" max="100"')}</div><p class="muted">Percentage mode uses each year's opening total portfolio value. Dollar mode starts with your first-year amount and compounds it by the annual growth percentage each following year. For example, $40,000 with 3% growth becomes $41,200 in the second withdrawal year. Use 0% for a constant amount; inflation is not added again automatically. Withdrawals begin in the selected year and occur at year end.</p><h2>Cash first, then proportional sales</h2><p>Use available plan cash first. If more is needed, the default sells the same proportion of each liquid investment or manual account total. Non-liquid positions are excluded. You can customize the sources below.</p><details><summary>Customize investment sources (optional)</summary><p class="muted">Percentages apply to the amount still needed after cash. Leave proportional selected for automatic allocation by investment value.</p>${select('allocationMode','Investment sale allocation',[['proportional','Proportional to investment values'],['custom','Use my percentages']],r.allocationMode||'proportional')}<div id="retirement-allocations"><p class="muted">Enter percentages totaling 100%. A source with 0% is not sold. If a selected source runs out, the unmet amount is reported as a shortfall rather than taken from other sources.</p><div class="grid-form">${valuationHoldings(plan).filter(h=>h.retirementEligible!==false).map((h,i)=>field('allocation_'+i,esc((h.symbol||h.name)+' · '+(h.account||h.name))+' (%)',(r.allocations||[]).find(a=>a.id===h.id)?.percent??0,'number','min="0" max="100"')).join('')}</div></div></details><p class="muted">Informational holdings inside manual-total accounts are not counted twice. This is a projection; no broker trades are placed. Taxes, penalties and sale fees are not included. Existing contributions and other withdrawals continue separately; do not enter this retirement spending again elsewhere.</p><div class="form-actions"><button class="primary">Save retirement plan</button></div></form></section><section class="panel"><h2>Projected retirement funding</h2><p class="muted">Based on saved settings. Investment sales fund the withdrawal and are not deducted a second time.</p>${r.enabled&&plan.modules?.retirement!==false?`<div class="table-wrap"><table><thead><tr><th>Year</th><th>Requested</th><th>From cash</th><th>Investment sales</th><th>Withdrawn</th><th>Shortfall</th></tr></thead><tbody>${rows.filter(y=>y.year>=r.startYear).map(y=>`<tr><td>${y.year}</td>${['retirementRequested','retirementCash','retirementSales','retirementWithdrawal','retirementShortfall'].map(k=>`<td>${money(y[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${r.startYear>rows.at(-1).year?'<p class="muted">The first withdrawal is beyond your projection horizon. Extend it in Plan settings to see withdrawals.</p>':''}`:'<p class="muted">Enable and save a retirement withdrawal plan to see its funding breakdown.</p>'}</section>`;}
function settings(){const s=plan.settings;return heading('Set the foundation.','Your planning horizon and household details. Salary and cash flows are in Funding.')+`<section class="panel"><form id="settings-form"><div class="grid-form">${field('name','Plan name',s.name,'text','required maxlength="160"')}${field('startYear','Starting year',s.startYear,'number','required min="1900" max="2200"')}${field('years','Projection length (years)',s.years,'number','required min="1" max="100"')}${field('primaryAge','Primary starting age (optional)',s.primaryAge,'number','min="0" max="120"')}${field('spouseAge','Spouse starting age (optional)',s.spouseAge,'number','min="0" max="120"')}</div><p class="muted">Ages are saved as household context. This planner does not apply age-based retirement or tax rules. Changing the starting year changes the projection window; dated trades and overrides keep their original years.</p><div class="form-actions"><button class="primary">Save plan settings</button></div></form></section>${method()}`;}
function dataView(){return heading('Your data. Wherever you plan.','A local database with a portable, versioned backup file.')+`<section class="panel"><h2>Named plans</h2><p class="muted">Current plan: <b>${esc(plan.settings.name)}</b>. ${planSummaries.length} saved plan${planSummaries.length===1?'':'s'} on this browser. Use the Plan selector above to switch; each plan keeps its own investments and assumptions.</p>${btn('+ New named plan','new-plan','','primary')}</section><div class="two-col"><section class="panel"><h2>Move your plan to another machine</h2><div class="step"><b>1</b><div>Export your database<p>One JSON file contains accounts, holdings, bonds, annuities, transactions, module choices, annual assumptions and settings.</p></div></div><div class="step"><b>2</b><div>Move the file<p>Copy it using a drive or your preferred private storage.</p></div></div><div class="step"><b>3</b><div>Import on the other machine<p>Open this planner and select your backup below. Review the contents before replacing only the current named plan.</p></div></div><div class="actions">${btn('↓ Export database','export','','primary')}<button data-action="choose-database">↑ Import database</button><input type="file" id="database-file" accept=".json,application/json" hidden></div></section><section class="panel"><h2>Saved on this browser</h2><p class="metric-inline">${(plan.accounts||[]).length} accounts · ${plan.holdings.length} investments</p><p class="muted">${plan.trades.length} transactions · ${plan.overrides.length} holding overrides<br>${(plan.bonds||[]).length} fixed-income positions · ${(plan.annuities||[]).length} annuities<br>Database schema version 1</p><p class="muted">No account or cloud service is needed. Clearing browser/site data or using private browsing can remove local records. Export a backup regularly.</p><p class="muted">Backups are readable, unencrypted files. Store them somewhere private. Imports replace only the current named plan. Other saved plans remain intact. Export one backup per plan; backups do not merge or sync machines.</p>${btn('Request durable browser storage','persist')}</section></div><section class="panel danger-zone"><h2>Clear current plan</h2><p class="muted">Clear only the current named plan. Export a backup first. Other saved plans and backup files are unaffected.</p>${btn('Clear saved data…','clear','','danger')}${undoPlan?btn('Undo last removal / replacement','undo'):''}</section><section class="panel"><h2>Annual maintenance</h2><p class="muted">Update annual assumptions in Yearly assumptions, or import an annual data file. Your personal records stay separate from the app files. Software updates at the same browser address keep the database intact.</p><a href="#annual">Manage annual assumptions →</a></section>`;}
function download(filename,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function backupPlan(){return {...structuredClone(plan),annualData:structuredClone(effectiveAnnual())};}
async function remove(kind,id){const next=structuredClone(plan),old=structuredClone(plan);if(kind==='holding'){const h=next.holdings.find(x=>x.id===id);openEditor('Remove investment?',`<p>Remove <b>${esc(h.name)}</b> and its linked transactions and annual overrides?</p><p class="muted">You can undo this removal in Data & backups during this session.</p>`,async()=>{next.holdings=next.holdings.filter(x=>x.id!==id);next.trades=next.trades.filter(x=>x.holdingId!==id);next.overrides=next.overrides.filter(x=>x.holdingId!==id);await commit(next);undoPlan=old;});return;}
if(kind==='trade')next.trades=next.trades.filter(x=>x.id!==id);if(kind==='override')next.overrides=next.overrides.filter(x=>x.holdingId+':'+x.year!==id);if(kind==='year'){next.annualData=structuredClone(effectiveAnnual());next.annualData.years=next.annualData.years.filter(y=>y.year!==Number(id));}await commit(next);undoPlan=old;render();toast('Removed. Undo is available in Data & backups.');}
function unsavedForm(){return [...document.querySelectorAll('main form input,main form select')].some(e=>e.tagName==='SELECT'?[...e.options].some(o=>o.selected!==o.defaultSelected):e.type==='checkbox'?e.checked!==e.defaultChecked:e.value!==e.defaultValue);}
async function activateNamedPlan(id){if(saving||!storageReady)throw Error('Reload or finish the current save before switching plans.');plan=await database.selectPlan(id);planSummaries=await database.listPlans();undoPlan=null;quoteReport='';channel?.postMessage('changed');status('✓ Saved on this browser');render();toast('Opened '+plan.settings.name+'.');}
function newNamedPlan(){openEditor('Create a new named plan',`${field('planName','New plan name','','text','required maxlength="160"')}<p>Your current plan <b>${esc(plan.settings.name)}</b> stays saved. The new plan starts blank.</p>${unsavedForm()?'<p class="notice">Unsaved entries on the current screen will be discarded. Cancel and save them first if you want to keep those entries.</p>':''}`,async f=>{if(saving||!storageReady)throw Error('Reload or finish saving before creating a plan.');const next=emptyPlan();next.settings.name=f.text('planName');next.annualData=structuredClone(annual);if(plan.modules)next.modules=structuredClone(plan.modules);plan=await database.createPlan(next);planSummaries=await database.listPlans();undoPlan=null;quoteReport='';channel?.postMessage('changed');status('✓ Saved on this browser');toast('New plan created. Your previous plan is preserved.');});$('#editor-form button[type="submit"]').textContent='Create plan';}
function attachPlanSelector(){const control=$('#plan-select');control.innerHTML=planSummaries.map(x=>`<option value="${esc(x.id)}" ${x.id===database.activeId()?'selected':''}>${esc(x.name)}</option>`).join('');control.onchange=()=>{const id=control.value;control.value=database.activeId();if(unsavedForm()){const target=planSummaries.find(x=>x.id===id);openEditor('Switch plans?',`<p>Switch to <b>${esc(target.name)}</b>?</p><p class="notice">Unsaved entries on the current screen will be discarded. Cancel and save them first if you want to keep those entries. Saved data remains intact.</p>`,()=>activateNamedPlan(id));$('#editor-form button[type="submit"]').textContent='Switch plan';}else activateNamedPlan(id).catch(err=>toast(err.message));};}
async function action(action,id){if(moduleUI.action(action,id))return;switch(action){case'new-plan':newNamedPlan();break;case'add-account':editAccount();break;case'edit-account':editAccount(id);break;case'remove-account':removeAccount(id);break;case'account-history':{const a=(plan.accounts||[]).find(a=>a.id===id);if(!a)throw Error('Account no longer exists.');openEditor('Account history · '+a.name,'<p class="muted">Account balance history includes deposits, withdrawals and value changes. Calculated accounts record the sum of linked starting values when those investments are updated. This is not investment performance.</p>'+historyView(a,esc,exact),()=>{});$('#editor-form button[type="submit"]').textContent='Done';break;}case'add-account-holding':editHolding(undefined,id);break;case'link-account-holding':linkAccountHolding(id);break;case'add-holding':editHolding();break;case'edit-holding':editHolding(id);break;case'holding-history':{const h=plan.holdings.find(h=>h.id===id);if(!h)throw Error('Investment no longer exists.');openEditor('History · '+(h.symbol||h.name),historyView(h,esc,exact),()=>{});$('#editor-form button[type="submit"]').textContent='Done';break;}case'add-trade':editTrade();break;case'edit-trade':editTrade(id);break;case'add-salary-year':editYear(undefined,true);break;case'edit-salary-year':editYear(id,true);break;case'add-year':editYear();break;case'edit-year':editYear(id);break;case'add-override':editOverride();break;case'edit-override':editOverride(id);break;case'remove-holding':case'remove-trade':case'remove-override':case'remove-year':await remove(action.slice(7),id);break;
case'earlier-trade':{const next=structuredClone(plan),i=next.trades.findIndex(t=>t.id===id),t=next.trades[i];let j=i-1;while(j>=0&&next.trades[j].year!==t.year)j--;if(j<0){toast('Already the first transaction in this year.');break;}[next.trades[i],next.trades[j]]=[next.trades[j],next.trades[i]];await commit(next);render();break;}
case'export':download('investment-planner-database-'+new Date().toISOString().slice(0,10)+'.json',database.serialize(backupPlan()));toast('Database exported. Keep it somewhere private.');break;
case'export-annual':download('annual-assumptions.json',JSON.stringify(effectiveAnnual(),null,2));break;
case'export-csv':{const rows=project(plan,effectiveAnnual()).rows,keys=['year','opening','external','retirementRequested','retirementCash','retirementSales','retirementShortfall','retirementWithdrawal','bondBalance','bondPurchases','bondInterest','bondRedemptions','annuityIncome','growth','income','annuityPremiums','fees','cash','total','real'];download('portfolio-projection.csv',keys.join(',')+'\r\n'+rows.map(r=>keys.map(k=>k==='year'?r[k]:r[k].toFixed(2)).join(',')).join('\r\n'),'text/csv');break;}
case'persist':toast(navigator.storage?.persist&&await navigator.storage.persist()?'Durable storage granted. Keep backups too.':'Browser did not grant durable storage. Export regular backups.');break;
case'choose-annual':$('#annual-file').click();break;
case'choose-database':$('#database-file').click();break;
case'update-prices':await updatePrices();break;
case'configure-prices':configurePrices();break;
case'apply-prices':if(config.quoteMode==='disabled')throw Error('Enter starting prices manually in the store edition.');openEditor('Use latest quotes as starting prices?',`<p>This changes the starting valuation and every future projection. Shares, cost basis and your starting year stay unchanged.</p><p class="notice">For a historical plan, keep your historical starting prices. Quotes can be delayed or from an earlier market session; review their dates first.</p>`,async()=>{const old=structuredClone(plan),next=structuredClone(plan);for(const h of next.holdings)if(h.quote&&h.valuationMode!=='dollars'){h.price=h.quote.price;recordSnapshot(h,{value:h.quote.price,source:'api',recordedAt:h.quote.retrievedAt,marketTime:h.quote.marketTime});}await commit(next);undoPlan=old;});break;
case'undo':{if(!undoPlan)break;const old=undoPlan;await commit(old);undoPlan=null;render();toast('Previous plan restored.');break;}
case'clear':openEditor('Clear current plan?',`<p class="notice error"><b>This permanently clears all saved entries in ${esc(plan.settings.name)}.</b> Its investments, accounts, funding, transactions and assumptions will be reset. Export a backup first; without one, the cleared entries cannot be restored.</p><p>Other named plans and backup files are unaffected.</p>${btn('Export current plan backup now','export')}<label style="margin-top:18px">Type CLEAR to confirm<input name="confirmation" required pattern="CLEAR" autocomplete="off"></label>`,async f=>{if(f.text('confirmation')!=='CLEAR')throw Error('Type CLEAR to confirm.');const next=emptyPlan();next.settings.name=plan.settings.name;await commit(next);undoPlan=null;quoteReport='';quoteKey='';sessionStorage.removeItem('quote-consent');toast('Current plan cleared. Other plans were preserved.');});$('#editor-form button[type="submit"]').textContent='Clear current plan';break;

}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action,b.dataset.id).catch(err=>toast(err.message));}});
function render(){attachPlanSelector();const view=currentView();$('#section-title').textContent=titleMap[view];document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+view);if(a.hash==='#'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});try{$('#content').innerHTML=({overview,accounts:accountsView,holdings,trades,funding,retirement,annual:annualView,settings,data:dataView,modules:moduleUI.modules,bonds:moduleUI.bonds,annuities:moduleUI.annuities,other:moduleUI.other}[view])();}catch(e){$('#content').innerHTML=`<div class="notice error">${esc(e.message)}</div><a href="#settings">Edit settings</a> · <a href="#holdings">Edit holdings</a> · <a href="#data">Export database</a>`;return;}
moduleUI.attach();
attachQuoteUI(view);
if(config.quoteMode!=='disabled'&&quoteReport)$('#content').insertAdjacentHTML('afterbegin',quoteReport);
if($('#holding-search'))$('#holding-search').oninput=e=>{let visible=0;document.querySelectorAll('[data-holding]').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase());if(!row.hidden)visible++;});$('#filter-empty').hidden=visible>0;};
if($('#settings-form'))$('#settings-form').onsubmit=async e=>{e.preventDefault();const next=structuredClone(plan),f=formData(e.target);next.settings={...next.settings,name:f.text('name')};for(const k of ['startYear','years'])next.settings[k]=f.num(k);for(const k of ['primaryAge','spouseAge'])next.settings[k]=f.nullable(k);try{await commit(next);toast('Plan settings saved.');render();}catch(err){toast(err.message);}};
if($('#retirement-form')){const form=$('#retirement-form'),toggle=()=>{form.elements.rate.closest('label').hidden=form.elements.mode.value!=='percent';form.elements.amount.closest('label').hidden=form.elements.mode.value!=='dollars';form.elements.amountGrowth.closest('label').hidden=form.elements.mode.value!=='dollars';$('#retirement-allocations').hidden=form.elements.allocationMode.value!=='custom';};form.elements.mode.onchange=toggle;form.elements.allocationMode.onchange=toggle;toggle();form.onsubmit=async e=>{e.preventDefault();const f=formData(e.target),next=structuredClone(plan);next.settings.retirement={enabled:f.checked('enabled'),startYear:f.num('startYear'),mode:f.text('mode'),rate:f.num('rate'),amount:f.num('amount'),amountGrowth:f.num('amountGrowth'),allocationMode:f.text('allocationMode'),allocations:valuationHoldings(plan).filter(h=>h.retirementEligible!==false).map((h,i)=>({id:h.id,percent:f.num('allocation_'+i)}))};try{await commit(next);toast('Retirement plan saved.');render();}catch(err){toast(err.message);}};}
if($('#funding-form')){const form=$('#funding-form'),toggle=()=>{form.elements.cashAmount.closest('label').hidden=form.elements.cashDirection.value==='none';};form.elements.cashDirection.onchange=toggle;toggle();form.onsubmit=async e=>{e.preventDefault();const next=structuredClone(plan),f=formData(e.target);for(const k of ['cash','primarySalary','spouseSalary'])next.settings[k]=f.num(k);for(const k of ['primarySalaryEndYear','spouseSalaryEndYear'])next.settings[k]=f.nullable(k);next.annualData=structuredClone(effectiveAnnual());next.annualData.defaults.salaryGrowth=f.num('salaryGrowth');next.settings.cashContribution=f.text('cashDirection')==='none'?0:f.num('cashAmount')*(f.text('cashDirection')==='withdrawal'?-1:1);try{await commit(next);toast('Funding saved.');render();}catch(err){toast(err.message);}};}
if($('#annual-defaults'))$('#annual-defaults').onsubmit=async e=>{e.preventDefault();const next=structuredClone(plan),f=formData(e.target);next.annualData=structuredClone(effectiveAnnual());next.annualData.defaults={...next.annualData.defaults,inflation:f.num('inflation')};try{await commit(next);toast('Annual defaults saved.');render();}catch(err){toast(err.message);}};
for(const id of ['database-file','annual-file'])if($('#'+id))$('#'+id).onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10000000)throw Error('File exceeds 10 MB.');const text=await file.text();if(id==='database-file'){const incoming=database.parse(text);openEditor('Review database import',`<p><b>${esc(incoming.settings.name)}</b></p><p>${(incoming.accounts||[]).length} accounts · ${incoming.holdings.length} investments · ${incoming.trades.length} transactions · ${incoming.overrides.length} overrides · ${(incoming.bonds||[]).length} bonds/CDs/treasuries · ${(incoming.annuities||[]).length} annuities</p><p class="notice">This replaces the local plan. Your current plan can be restored with Undo during this session.</p>`,async()=>{const old=structuredClone(plan);await commit(incoming);undoPlan=old;toast('Database imported.');});}else{const incoming=validateAnnual(JSON.parse(text));openEditor('Review annual data import',`<p>${incoming.years.length} year-specific entries.</p><p>Defaults: ${pct(incoming.defaults.inflation)} inflation, ${pct(incoming.defaults.salaryGrowth)} salary growth.</p><p class="muted">This replaces annual assumptions only. Holdings and transactions remain intact.</p>`,async()=>{const old=structuredClone(plan);await commit({...structuredClone(plan),annualData:incoming});undoPlan=old;});}}catch(err){toast('Import rejected: '+err.message);}finally{e.target.value='';}};
}
window.addEventListener('hashchange',render);
function accountValue(a,p=plan){return ['manual','mixed'].includes(a.valuationMode)?a.price:p.holdings.filter(h=>h.accountId===a.id).reduce((sum,h)=>sum+startingHoldingValue(h),0)+initialBondValue({...p,bonds:(p.bonds||[]).filter(b=>b.accountId===a.id)})+(p.otherInvestments||[]).filter(h=>h.accountId===a.id).reduce((sum,h)=>sum+h.value,0);}
function accountHoldingsPanel(){return (plan.accounts||[]).map(a=>{const linked=plan.holdings.filter(h=>h.accountId===a.id);return `<section class="panel"><div class="panel-head"><div><h2>${esc(a.name)}: stocks & funds</h2><p class="muted">${a.valuationMode==='manual'?'Optional details within your manual account total; not counted again.':a.valuationMode==='mixed'?'Track just your selected investments. The remaining balance stays in this account automatically.':'These investments determine this account’s balance.'}</p></div></div>${a.valuationMode==='mixed'?`<div class="notice">Total account: <b>${money(a.price)}</b> · Selected investments: <b>${money(trackedAccountValue(plan,a.id))}</b> · Remaining investments: <b>${money(accountRemainder(plan,a))}</b></div>`:''}<div class="actions">${btn('+ Add stock/fund','add-account-holding',a.id,'primary')}${btn('Link existing stock/fund','link-account-holding',a.id)}</div>${linked.length?`<div class="table-wrap"><table><thead><tr><th>Linked investment</th><th class="num">Starting value</th><th>Manage</th></tr></thead><tbody>${linked.map(h=>`<tr><td><b>${esc(h.symbol||h.name)}</b><span class="sub">${esc(h.name)}</span></td><td class="num">${exact(startingHoldingValue(h))}</td><td>${btn('Edit investment','edit-holding',h.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No stocks or funds linked yet. Add a new investment or link one you already entered.</p>'}</section>`;}).join('');}
function linkAccountHolding(accountId){const account=(plan.accounts||[]).find(a=>a.id===accountId);if(!account)return;const choices=plan.holdings.filter(h=>h.accountId!==accountId);if(!choices.length){toast('No other investments to link. Use Add stock/fund to create one in this account.');return;}openEditor(`Link investment to ${account.name}`,`${select('holdingId','Existing stock or fund',[['','Select an investment'],...choices.map(h=>[h.id,`${h.symbol||h.name} — ${h.accountId?(plan.accounts||[]).find(a=>a.id===h.accountId)?.name:'Standalone investment'}`])],'')}<p class="muted">This moves the selected investment into ${esc(account.name)} without creating a duplicate. Its shares, prices, assumptions and planned trades stay with it. You can change the Portfolio account in its edit form later.</p><p class="notice">${account.valuationMode==='manual'?'This account uses a manual total. The linked investment becomes informational and is no longer counted separately; its individual trades will be excluded.':'This account’s balance will include the linked investment. Any previous account calculated from holdings will no longer include it.'}</p>`,async f=>{const next=structuredClone(plan),h=next.holdings.find(h=>h.id===f.text('holdingId'));if(!h)throw Error('Select an investment to link.');h.accountId=account.id;h.account=account.name;await commit(next);toast('Investment linked to '+account.name+'.');});}
function accountsView(){const accounts=plan.accounts||[];return heading('Track the account your way.','Use one total dollar balance, individual investments, or a mixture of both across accounts.',btn('+ Add account','add-account','','primary'))+`<div class="notice">You do not need to enter the stocks inside an account. Choose <b>Manual account total</b> and enter its dollar balance. Use Account total with selected holdings to track a few stocks and keep the rest as an automatic remaining balance. Manual-total mode keeps linked records informational.</div><section class="panel"><h2>Your accounts</h2>${accounts.length?`<div class="table-wrap"><table><thead><tr><th>Account</th><th>Valuation source</th><th class="num">Starting balance</th><th>Periodic investment</th><th>Actions</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><b>${esc(a.name)}</b><span class="sub">${esc(a.owner)} · ${esc(a.taxType)}</span></td><td><span class="tag">${a.valuationMode==='manual'?'Manual account total':a.valuationMode==='mixed'?'Account total with selected holdings':'Sum of individual holdings'}</span><span class="sub">${plan.holdings.filter(h=>h.accountId===a.id).length} optional linked holdings</span></td><td class="num">${exact(accountValue(a))}</td><td>${a.valuationMode==='holdings'?'Set per holding':a.contributionMode==='none'?'None':a.contributionMode==='fixed'?money(a.contribution)+'/year':'Salary percentage'}</td><td>${btn('Edit / update balance','edit-account',a.id,'text-button')}${btn('Historical graph','account-history',a.id,'text-button')}${btn('Remove','remove-account',a.id,'text-button danger')}</td></tr>`).join('')}</tbody></table></div>`:empty('One account. One number.','Have ten stocks in a brokerage account? Enter just the account total and your planning assumptions.',btn('+ Add account','add-account','','primary'))}</section>${accountHoldingsPanel()}<section class="panel"><h2>Choose the level of detail</h2><div class="two-col"><div><h3>Account total with selected holdings</h3><p class="muted">Enter the full account total, then link only the stocks you want to track. The app subtracts their values and projects the remaining investments as one automatic balance. You do not need to list or assign the other investments.</p><h3>Manual account total</h3><p class="muted">Enter and periodically update the total yourself. Growth, dividends and periodic investments are set for the whole account. Individual stock records are optional and informational; price refresh never changes the manual account balance.</p></div><div><h3>Individual holdings</h3><p class="muted">Link stocks and funds to the account. Their starting values and assumptions make up its projection. Retrieve quotes, then explicitly apply them as starting prices when you want to update the account valuation.</p></div></div><p class="muted">Switching modes changes the valuation source. The manual amount and linked holdings stay saved for switching back. With individual holdings selected, unlisted stocks and uninvested account cash are not included; enter them explicitly. Existing trades for excluded positions are flagged and skipped.</p></section>`;}
function editAccount(id){const old=(plan.accounts||[]).find(a=>a.id===id),a=old?structuredClone(old):{id:uid(),name:'',account:'',symbol:'',type:'Other',shares:1,price:0,basis:0,owner:'Both',taxType:'Taxable',growth:0,yield:0,reinvest:true,contributionMode:'none',contribution:0,contributionGrowth:0,primaryPct:0,spousePct:0,valuationMode:'manual'};
openEditor(old?'Update account':'Add an account',`<div class="grid-form">${field('name','Account name',a.name,'text','required maxlength="160"')}${select('valuationMode','Track this account using',[['manual','Manual account total'],['mixed','Account total with selected holdings'],['holdings','Individual holdings']],a.valuationMode)}${select('owner','Owner',['Primary','Spouse','Both'],a.owner)}${select('taxType','Account category',['Taxable','Traditional retirement','Roth'],a.taxType)}</div><label class="check"><input type="checkbox" name="recordAccountHistory" checked>Record this account balance in history when saving</label><div id="account-manual-fields"><p class="muted">Enter the entire account balance. In selected-holdings mode, the remainder is calculated automatically.</p><p id="account-remainder-preview" class="notice" hidden></p><div class="grid-form">${field('price','Total account balance ($)',a.price,'number','required min="0"')}${field('basis','Total cost basis ($, optional)',a.basis||'','number','min="0" placeholder="Not needed for projections"')}${field('growth','Annual price growth (%)',a.growth,'number','required min="-100" max="100"')}${field('yield','Annual dividend yield (%)',a.yield,'number','required min="0" max="100"')}<label class="check"><input type="checkbox" name="reinvest" ${a.reinvest?'checked':''}>Keep dividends in account</label>${select('contributionMode','Periodic investment source',[['none','None'],['fixed','Fixed dollar amount'],['salary','Salary percentage']],a.contributionMode)}${field('contribution','Annual contribution (+) / withdrawal (−)',a.contribution,'number','required')}${field('contributionGrowth','Annual contribution growth (%)',a.contributionGrowth,'number','required min="-100" max="100"')}${field('primaryPct','Primary salary contribution (%)',a.primaryPct,'number','required min="0" max="100"')}${field('spousePct','Spouse salary contribution (%)',a.spousePct,'number','required min="0" max="100"')}</div></div><p class="muted">In selected-holdings mode, account growth, dividends and periodic contributions apply to the remaining investments only; selected holdings use their own assumptions. Account-level trades sell or buy the remainder. Selected values must not exceed the total. For individual holdings, add stocks and funds separately and select this account. The account's manual balance and assumptions are then excluded. Price growth excludes dividends; use a zero yield if growth already represents total return.</p>`,async f=>{const next=structuredClone(plan),value={...a};for(const k of ['name','owner','taxType','valuationMode','contributionMode'])value[k]=f.text(k);value.account=value.name;for(const k of ['price','basis','growth','yield','contribution','contributionGrowth','primaryPct','spousePct'])value[k]=f.num(k);value.reinvest=f.checked('reinvest');if(f.checked('recordAccountHistory'))recordSnapshot(value,{kind:'value',value:value.valuationMode==='holdings'?accountValue(value,next):value.price,source:value.valuationMode==='holdings'?'calculated':'manual'});next.accounts??=[];const i=next.accounts.findIndex(x=>x.id===a.id);if(i<0)next.accounts.push(value);else next.accounts[i]=value;for(const h of next.holdings)if(h.accountId===a.id)h.account=value.name;await commit(next);});
const form=$('#editor-form'),toggle=()=>{$('#account-manual-fields').hidden=form.elements.valuationMode.value==='holdings';const mixed=form.elements.valuationMode.value==='mixed',out=$('#account-remainder-preview'),tracked=trackedAccountValue(plan,a.id),total=Number(form.elements.price.value);out.hidden=!mixed;out.textContent=`Selected investments: ${money(tracked)}. Remaining investments: ${money(Math.max(0,total-tracked))}.`+(tracked>total?' Selected investments exceed the account total.':'');for(const k of ['contribution','contributionGrowth'])form.elements[k].closest('label').hidden=form.elements.contributionMode.value!=='fixed';for(const k of ['primaryPct','spousePct'])form.elements[k].closest('label').hidden=form.elements.contributionMode.value!=='salary';};form.elements.valuationMode.onchange=toggle;form.elements.contributionMode.onchange=toggle;form.elements.price.oninput=toggle;toggle();}
function removeAccount(id){const a=plan.accounts.find(a=>a.id===id);openEditor('Remove account?',`<p>Remove <b>${esc(a.name)}</b>, its optional linked holdings, fixed-income records, annuities, planned transactions and overrides?</p><p class="muted">Undo is available in Data & backups during this session.</p>`,async()=>{const old=structuredClone(plan),next=structuredClone(plan),removed=new Set([id,...next.holdings.filter(h=>h.accountId===id).map(h=>h.id)]);next.accounts=next.accounts.filter(a=>a.id!==id);for(const k of ['bonds','annuities','otherInvestments'])if(next[k])next[k]=next[k].filter(x=>x.accountId!==id);next.holdings=next.holdings.filter(h=>!removed.has(h.id));next.trades=next.trades.filter(t=>!removed.has(t.holdingId));next.overrides=next.overrides.filter(o=>!removed.has(o.holdingId));await commit(next);undoPlan=old;});}
function attachQuoteUI(view){if(view==='overview')$('.page-heading .actions').insertAdjacentHTML('beforeend',btn('+ Add account','add-account'));if(config.quoteMode==='disabled'||!['overview','holdings'].includes(view))return;$('.page-heading .actions').insertAdjacentHTML('afterbegin',btn(refreshing?'Updating…':'↻ Update prices','update-prices'));
const quotes=plan.holdings.filter(h=>h.quote&&h.valuationMode!=='dollars');if(!quotes.length)return;$('.page-heading').insertAdjacentHTML('afterend',`<section class="panel"><div class="panel-head"><div><h2>Latest retrieved prices</h2><p class="muted">Quotes are separate from your starting prices. Delays and coverage depend on your data subscription.</p></div>${btn('Use as starting prices…','apply-prices')}</div><div class="table-wrap"><table><thead><tr><th>Investment</th><th>Provider instrument</th><th class="num">Latest price</th><th>Market time (provider)</th><th>Retrieved</th></tr></thead><tbody>${quotes.map(h=>`<tr><td>${esc(h.symbol)}<span class="sub">${esc(h.account)}</span></td><td>${esc(h.quote.name)}<span class="sub">${esc(h.quote.exchange)} · ${esc(h.quote.source)}</span></td><td class="num">${exact(h.quote.price)}</td><td>${esc(h.quote.marketTime||'Not supplied')}</td><td>${esc(new Date(h.quote.retrievedAt).toLocaleString())}</td></tr>`).join('')}</tbody></table></div></section>`);}
function configurePrices(){if(config.quoteMode==='disabled')throw Error('Automatic price connections are disabled in the store edition. Enter balances or prices manually.');openEditor('Connect price updates',`<p class="muted">The personal web edition uses your Twelve Data API key. It stays in this tab's memory and is excluded from the database and backups.</p><label>API key<input name="apiKey" type="password" autocomplete="off" required></label><p class="muted">Clicking Save changes sends only your ticker symbols to Twelve Data to retrieve quotes. Holdings, share counts and balances are not sent. Coverage, rate limits and fund availability depend on your subscription.</p><p class="muted">Once connected, use Update prices for a single-click refresh during this session.</p>`,async f=>{quoteKey=f.text('apiKey');if(!quoteKey)throw Error('Enter an API key.');await refreshQuotes();});}
async function updatePrices(){if(config.quoteMode==='disabled')throw Error('Automatic price connections are disabled in the store edition. Enter balances or prices manually.');if(refreshing)return;if(!plan.holdings.some(h=>h.symbol&&h.valuationMode!=='dollars')){toast('Price updates require a ticker and Shares and share price mode. Dollar-only balances are entered manually.');return;}if(config.quoteMode==='personal'&&!quoteKey){configurePrices();return;}if(config.quoteMode==='proxy'&&!sessionStorage.getItem('quote-consent')){openEditor('Update investment prices',`<p>Ticker symbols will be sent to the configured quote service. Share counts, balances and account names are not sent.</p><p class="muted">Data coverage and delays depend on the service subscription.</p>`,async()=>{sessionStorage.setItem('quote-consent','yes');await refreshQuotes();});return;}await refreshQuotes();}
async function refreshQuotes(){if(config.quoteMode==='disabled')throw Error('Automatic price connections are disabled in the store edition. Enter balances or prices manually.');if(refreshing)return;if(!storageReady)throw Error('Reload the plan before updating prices.');refreshing=true;const before=JSON.stringify(plan);try{status('Retrieving prices…');const results=await fetchPrices(plan.holdings.filter(h=>h.valuationMode!=='dollars').map(h=>h.symbol),{key:quoteKey,mode:config.quoteMode,endpoint:config.quoteEndpoint,onProgress:(symbol,i,n)=>status(`Updating ${symbol} (${i+1}/${n})…`)});if(JSON.stringify(plan)!==before)throw Error('The plan changed during refresh. Retry to avoid overwriting changes.');const good=results.filter(r=>r.quote),bad=results.filter(r=>r.error);if(good.length)await commit(applyQuotes(plan,results));else status('Price update failed; previous prices retained',true);quoteReport=`<div class="notice ${good.length?'':'error'}" role="status"><b>${good.length} symbols updated${bad.length?', '+bad.length+' unavailable':''}.</b> Previous prices are retained for failures.${bad.length?`<div class="warning-list">${bad.map(r=>`<div>${esc(r.symbol)}: ${esc(r.error)}</div>`).join('')}</div>`:''}${config.quoteMode==='personal'?btn('Change API key','configure-prices','','text-button'):''}</div>`;render();}catch(e){status('Price refresh failed — previous prices retained',true);throw e;}finally{refreshing=false;document.querySelectorAll('[data-action="update-prices"]').forEach(b=>b.textContent='↻ Update prices');}}
async function start(){try{const response=await fetch('data/annual.json');if(!response.ok)throw Error('Could not load annual assumptions.');annual=validateAnnual(await response.json());}catch(e){$('#content').innerHTML=`<div class="notice error">${esc(e.message)} Refresh after restoring the data file.</div>`;status('App data unavailable',true);return;}try{plan=await database.read();planSummaries=await database.listPlans();storageReady=true;status('✓ Saved on this browser');}catch(e){status('Database unavailable — editing disabled',true);$('#content').innerHTML=`<div class="notice error">The local database could not be opened: ${esc(e.message)}. Existing records have not been overwritten. Enable browser storage and reload.</div>`;return;}if('BroadcastChannel'in window){channel=new BroadcastChannel('stocks-funds-plan');channel.onmessage=()=>{status('Another tab changed or switched plans. Reload before editing.',true);storageReady=false;};if(database.didMigrate())channel.postMessage('changed');}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('serviceworker.js').catch(()=>{});}
const moduleUI=createModuleUI({getPlan:()=>plan,getAnnual:effectiveAnnual,heading,field,select,btn,esc,money,openEditor,commit,render,toast,formData});
start();

function overviewAccounts(){const accounts=plan.accounts||[];return `<section class="panel overview-accounts"><div class="panel-head"><div><h2>Accounts</h2><p class="muted">Update balances or view recorded account history. These totals summarize the portfolio; linked investments are not counted twice.</p></div><a href="#accounts">Manage accounts →</a></div>${accounts.length?`<div class="table-wrap"><table><thead><tr><th>Account</th><th>Valuation source</th><th class="num">Starting balance</th><th>Actions</th></tr></thead><tbody>${accounts.map(a=>`<tr><td><b>${esc(a.name)}</b><span class="sub">${esc(a.owner)} · ${esc(a.taxType)}</span></td><td>${a.valuationMode==='manual'?'Manual account total':a.valuationMode==='mixed'?'Total with selected holdings':'Sum of individual holdings'}</td><td class="num">${exact(accountValue(a))}</td><td>${btn('Edit / update balance','edit-account',a.id,'text-button')}${btn('Historical graph','account-history',a.id,'text-button')}</td></tr>`).join('')}</tbody></table></div>`:empty('Track an account balance','Enter one account total, or link individual investments.',btn('+ Add account','add-account','','primary'))}</section>`;}
